    mediaMonDesc: 'தனிப்பயன் பேவால்களுக்குப் பின்னால் பூட்டப்பட்ட புகைப்படங்கள் மற்றும் வீடியோக்களைப் பகிரவும், எந்தவொரு ஆதரவு டோக்கனுக்கும் பிரீமியம் உள்ளடக்கத்தைத் திறக்க பெறுநர்களை அனுமதிக்கிறது.',
    flexiblePricing: 'நெகிழ்வான விலை நிர்ணயம்',
    flexiblePricingDesc: 'பிரத்தியேக செய்தி உள்ளடக்கத்திற்கு DeHub டோக்கன்கள், USDC, ETH அல்லது ஏதேனும் ஆதரிக்கப்படும் கிரிப்டோகரன்சியில் தனிப்பயன் அன்லாக் விலையை அமைக்கவும்.',
    previewSystem: 'முன்னோட்ட அமைப்பு',
    previewSystemDesc: 'பெறுநர்கள் தெளிவான அன்லாக் விருப்பங்களுடன் செய்தி முன்னோட்டங்களைப் பார்க்கிறார்கள், எதிர்பார்ப்பை உருவாக்குகிறார்கள் மற்றும் ஈடுபாட்டை அதிகரிக்கிறார்கள்.',
    e2eTitle: 'எண்ட்-டு-எண்ட் என்க்ரிப்ஷன்',
    militaryGrade: 'இராணுவ-தர பாதுகாப்பு',
    militaryGradeDesc: 'அனைத்து செய்திகளும் இறுதி முதல் இறுதி வரை குறியாக்கம் செய்யப்படுகின்றன, நீங்களும் உங்கள் நோக்கம் கொண்ட பெறுநர்களும் மட்டுமே உங்கள் உரையாடல்களைப் படிக்க முடியும் என்பதை உறுதிசெய்கிறது.',
    privateByDesign: 'வடிவமைப்பால் தனிப்பட்டது',
    privateByDesignDesc: 'DeHub உட்பட எந்த மூன்றாம் தரப்பினரும் உங்கள் செய்தி உள்ளடக்கத்தை அணுக முடியாது. உங்கள் தனியுரிமை கிரிப்டோகிராஃபிக் நெறிமுறைகளால் உத்தரவாதம் அளிக்கப்படுகிறது.',
    secureMediaSharing: 'பாதுகாப்பான மீடியா பகிர்வு',
    secureMediaDesc: 'புகைப்படங்கள், வீடியோக்கள் மற்றும் கோப்புகள் பரிமாற்றத்திற்கு முன் குறியாக்கம் செய்யப்பட்டு பரவலாக்கப்பட்ட உள்கட்டமைப்பில் பாதுகாப்பாக சேமிக்கப்படுகின்றன.',
    messageTypes: 'செய்தி வகைகள் மற்றும் அம்சங்கள்',
    standardMessages: 'நிலையான செய்திகள்',
