    premiumContent: 'பிரீமியம் உள்ளடக்கம்',
    prem1: 'பேவால்-பாதுகாக்கப்பட்ட ஊடகம்',
    prem2: 'பிரத்தியேக புகைப்படம்/வீடியோ அணுகல்',
    prem3: 'தனிப்பயன் அன்லாக் விலை நிர்ணயம்',
