    feeTierTitle: 'கட்டண அடுக்கு அமைப்பு',
    feeTierSubtitle: 'பேட்ஜ் அடிப்படையிலான கட்டணக் குறைப்பு',
    feeTierDesc: 'எங்கள் புரட்சிகர கட்டண அமைப்பு DeHub டோக்கன் வைத்திருப்பவர்களுக்கு கணிசமாகக் குறைக்கப்பட்ட இயங்குதளக் கட்டணத்துடன் வெகுமதி அளிக்கிறது. நிலையான 10% கட்டணத்தில் தொடங்கி, அதிகரித்த டோக்கன் ஹோல்டிங்ஸ் மூலம் சம்பாதிக்கும் ஒவ்வொரு பேட்ஜ் அடுக்கும் கட்டணத்தை 0.69% குறைக்கிறது, இறுதியில் மெகலோடான் பேட்ஜ் வைத்திருப்பவர்களுக்கு வெறும் 1% ஐ எட்டுகிறது - இது எங்கள் மிகவும் அர்ப்பணிப்புள்ள சமூக உறுப்பினர்களுக்கு 99% கட்டணக் குறைப்பாகும்.',
    platformFeeStructure: 'பிளாட்ஃபார்ம் கட்டண அமைப்பு',
