    exampleSavings: 'எடுத்துக்காட்டு சேமிப்பு',
    feeDisclaimer: 'முக்கியமான கட்டண மறுப்பு',
    feeDisclaimerDesc: 'வெகுமானங்கள், சந்தாக்கள், பார்வைக்கு பணம் செலுத்துதல் மற்றும் watch2earn போன்கள் போன்ற சில சேவைகளுக்கு மட்டுமே கட்டணங்கள் பொருந்தும். பயனர்கள் ஆப் முழுவதும் மற்ற பயனர்களுக்கு டோக்கன்களை இலவசமாக அனுப்பலாம் மற்றும் பணப்பை முகவரி அல்லது தனிப்பட்ட விசை மேலாண்மை தேவையில்லை எனில் அதைச் செய்ய எங்கள் சுருக்கக் கருவிகளைப் பயன்படுத்தலாம்.',
