    raffleTitle: 'DeHub ராஃபிள்',
    raffleDescription: 'DeHub ராஃபிள் ஒரு பிளாக்செயின் அடிப்படையிலான பரவலாக்கப்பட்ட லாட்டரி அமைப்பு ஆகும்.',
    raffleHowTo: 'ராஃபிளில் எவ்வாறு பங்கேற்பது',
