    raffleStep4: 'வெற்றி பெற்றால் பரிசுகளைப் பெறுங்கள்',
    predictionTitle: 'DeHub கணிப்பு',
    predictionDescription: 'விளைவுகளைச் சரியாகக் கணிப்பதன் மூலம் வெகுமதிகளைப் பெறுங்கள்.',
    intro1: 'வீரர்கள் மற்றும் ஸ்ட்ரீமர்கள் நிறைந்த அணியாக, நாங்கள் பல வேடிக்கையான, இலவச ஆர்கேட் கேம்களை உருவாக்கி வெளியிட்டோம், மேலும் எங்கள் முதல் முதன்மை விளையாட்டு, லாஸ்ட் சாட் ஸ்டாண்டிங், முதல் எம்எம்ஏ போர் ராயல், யூபிசாஃப்ட் போன்றவற்றிலிருந்து வந்த தேவ்ஸ் குழு மற்றும் யுஎஃப்சி, ஒக்டாகன் மற்றும் பிஎஃப்எல் நட்சத்திரங்களுடன் பெரிதும் ஈடுபட்டுள்ள ஒரு ஸ்தாபக குழு, ஜார்ஜ் மஸ்விடல் போன்ற சாம்ப்களுடன் ஆவணப்படங்களை படமாக்கி, கோனோர் மெக்ரிகரின் பயிற்சியாளர் கவன்னாவின் கீழ் பயிற்சி பெற்றோம். ஆவணப்படங்கள் ஆண்ட்ரூ டேட்டின் போர் அறையின் தலைவரான லூக் பர்னாட் மற்றும் முன்னாள் யுஎஃப்சி ஸ்லக்கர் ஆகியோரால் DeHub இன் Behalf இல் படமாக்கப்பட்டது.',
    intro2: 'நிச்சயதார்த்தம், நேர்மறையான பின்னூட்ட சுழல்கள் மற்றும் பொது வளர்ச்சியை ஊக்குவிக்க எந்தவொரு நீர்த்துப்போகலும் அல்லது பணவீக்கமும் தேவையில்லை என்பதை உறுதிசெய்யும் கட்டண உருவாக்கத்தின் அடிப்படையில் ஒரு நாடகம் மற்றும் சம்பாதிக்க மாதிரி முற்றிலும் நீடிக்கிறது.',
    intro3: 'பொதுவான இலக்கை அடைய தொடர்ந்து கடினமாக உழைக்க குழு மற்றும் சமூகத்தை ஊக்குவிப்பதன் கூடுதல் நன்மையையும் இது கொண்டுள்ளது, அதிக பயனர்கள் எங்களிடம் உள்ளனர், அதிக வருவாய் ஈட்டுகிறோம், அதிக வெகுமதிகள் உருவாக்கப்படுகின்றன மற்றும் அதிக பயனர்களை நாம் ஈர்க்க முடியும்.',
    intro4: 'ஒரு உண்மையான சுய மேம்படுத்துதல் மற்றும் நிலையான சுற்றுச்சூழல் அமைப்பு.',
