    website: 'வலைத்தளம்',
    releasedTitle: 'தலைப்புகள் வெளியிடப்பட்டன',
    releasedIntro: 'ஐந்து விளையாட்டுகள் ஒரு உலாவி தாவலில், DeHub-க்குள் இயங்குகின்றன. நிறுவ எதுவும் இல்லை, வாங்க எதுவும் இல்லை — அவற்றில் மூன்று திறந்த மூலங்கள், இரண்டு DeHub க்காக உருவாக்கப்பட்டது.',
    chessTitle: 'கிங்ஸ் காம்பிட்',
    chessDesc: 'ஒவ்வொரு துண்டுக்கும் பின்னால் ஒரு இராணுவத்துடன் சினிமா 3D சதுரங்கம். மூன்று முரட்டுத்தனமான நாகரிகங்கள் நான்கு போர்க்களங்களில், மூன்று என்ஜின் வலிமைகளில், எலோவில் மதிப்பிடப்பட்ட ஆன்லைன் ஏணியுடன் ஒரு பளிங்கு பலகையில் அணிவகுத்து, வேலைநிறுத்தம் செய்து விழுகின்றன.',
    dutyTitle: 'கிளாட் ஆஃப் டூட்டி',
    dutyDesc: 'எந்தவொரு கலையையும் அனுப்பாத முதல் நபர் ஷூட்டர்: ஒவ்வொரு கண்ணி, அமைப்பு, ஆயுதம் மற்றும் ஒலி நிலை சுமைகள் இருக்கும்போது உங்கள் கணினியில் உருவாக்கப்படுகிறது. இது போர் கருப்பொருளுக்குள்ளும் மறைந்துள்ளது.',
    jungleTitle: 'ஜங்கிள் ட்ரெயில்',
    jungleDesc: 'ஒரு செயல்முறை உருவாக்கப்பட்ட மழைக்காட்ச்சியில் முதல் நபர் நடை — நூற்றுக்கணக்கான பூச்சிகள், வானிலை மற்றும் ஒரு நாள் சுழற்சி, அனைத்தும் உங்கள் வருகையுடன் வளர்ந்தது. இது ஜங்கில் தீமா உள்ளே மறைந்துள்ளது.',
    streetTitle: 'ஸ்ட்ரீட் ஸ்லேயர்',
    streetDesc: 'பேராசைமிக்க வங்கி மாஃபியாவின் தெருக்களை அகற்றி, கிளப்பை இந்த பக்கத்தில் ஸ்க்ரோலிங் பீட் \'எம் அப், DeHub க்கு ஆணையிடப்பட்டது மற்றும் ஸ்டுடியோ ஷூக் பிக்சலால் கட்டப்பட்டது. மூன்று போராளிகளில் ஒருவரைத் தேர்ந்தெடுத்து, பின்னர் குத்தி, உதைத்து, உங்கள் வழியைத் தொகுதிக்கு கீழே எறியுங்கள்.',
    trenchTitle: 'சார்டோபியா',
    trenchDesc: 'நீங்கள் நடக்கக்கூடிய ஒரு வர்த்தக தளம். பினான்ஸ், டெக்ஸ்ஸ்கிரீனர், வீடியோக்கள், உலாவி தாவல்கள் ஆகியவற்றிலிருந்து நேரடி ஊட்டங்களை எடுத்துச் செல்லும் மேசையைச் சுற்றி டஜன் கணக்கான திரை வளைவுகள் — சுவரில் நீங்கள் விரும்பும் எதையும். இதை ஹெட்செட்டிலும் உள்ளிடலாம்.',
    playArcade: 'அவை அனைத்தையும் DeHub ஆர்கேடில் விளையாடுங்கள்:',
    featuresTitle: 'முக்கிய அம்சங்கள்',
