    feature2: 'கிளாசிக் ஆர்கேட் மினி கேம்ஸ், போட்டிகள் & டாப் அடுக்கு சுயாதீன/இண்டி கேம்ஸ்',
    feature3: 'எங்கள் ஸ்ட்ரீமிங் ஆப்பில் கேமிங் உள்ளடக்கத்தை நேரடியாக ஸ்ட்ரீம் செய்யவும்',
