    disclaimer: 'பொறுப்புத்துறப்பு',
    disclaimerText: 'DeHub டோக்கன்கள் கண்டிப்பாக பயன்பாட்டு நோக்கங்களுக்காக, எந்தவொரு விளையாட்டு அல்லது ஆப்பில் உள்ள டிஜிட்டல் டோக்கன்கள் அல்லது நாணயங்கள் சங்கிலியில் செயல்படும் இடத்தைத் தவிர, கூடுதல் பயன்பாடு மற்றும் சரிபார்க்கக்கூடிய வெளிப்படைத்தன்மையின் முன்னோடியில்லாத அளவுகளை நாங்கள் வழங்க முடியும். மேற்கண்ட தரவு வெளிப்படைத்தன்மை, கல்வி மற்றும் தகவல் நோக்கங்களுக்காக மட்டுமே தொகுக்கப்பட்டுள்ளது. நாங்கள் வெளியிடும் டோக்கன்கள் அல்லது NFTகளை வாங்குவதால் ஏற்படும் நிதி இழப்புகளுக்கு DeHub மற்றும் அனைத்து துணை நிறுவனங்களும் பொறுப்பேற்காது. சந்தைகள் மிகவும் கொந்தளிப்பானவை. ஹேக்குகள், திறன் தோல்விகள் அல்லது தொழில்நுட்பப் பிழைகள் போன்ற தவிர்க்க முடியாத நிகழ்வுகள் காரணமாக உங்கள் பணம் முழுவதையும் நீங்கள் இழக்க நேரிடலாம். எனவே, நீங்கள் இழக்கக்கூடியதை மட்டுமே நீங்கள் முதலீடு செய்ய வேண்டும்.',
