    votingPower: 'வாக்களிப்பு ஆற்றல்',
    votingPowerDesc: 'உங்கள் வாக்களிப்பு ஆற்றல் உங்கள் ஸ்டேக் செய்யப்பட்ட DHB அளவிற்கு விகிதாசாரமானது',
    proposals: 'முன்மொழிவுகள்',
    proposalsDesc: 'எந்த டோக்கன் வைத்திருப்பவரும் வாக்கெடுப்புக்கு முன்மொழிவுகளை சமர்ப்பிக்கலாம்',
    treasury: 'கருவூலம்',
    treasuryDesc: 'சமூக கருவூலம் ஆளுகை வாக்கெடுப்பு மூலம் விநியோகிக்கப்படுகிறது',
    fairVoting: 'நியாயமான வாக்களிப்பு தர்க்கம்',
    fairVotingDesc: 'DeHub ஒரு சிறந்த வாக்களிக்கும் தர்க்கத்தை அறிமுகப்படுத்துகிறது, அங்கு பங்குதாரரின் எடை வரையறுக்கப்பட்ட அளவுகளால் பெருக்கப்படுகிறது, எந்தவொரு நிறுவனமும் நெறிமுறையை கட்டுப்படுத்த முடியாது என்பதை உறுதிசெய்கிறது, அதே நேரத்தில் பெரிய முதலீட்டாளர்களுக்கு விகிதாசாரமாக வெகுமதி அளிக்கப்படுகிறது. ஒவ்வொரு வாக்குக்கும் வாக்காளர் தற்போது 50 DeHub டோக்கன்களை எரிக்க வேண்டும் என்ற புதிய விளையாட்டு கோட்பாட்டையும் நாங்கள் இணைத்துள்ளோம். இது மோசமான நடிகர்களை அல்லது கையாளுதலை மேலும் ஊக்கப்படுத்துகிறது, அதே நேரத்தில் ஈடுபாட்டை ஊக்குவிக்கிறது, இது ஒவ்வொரு வாக்கெடுப்பிலும் அதிக பயனர்களை வாக்களிக்க ஊக்குவிக்கும்.',
    preventingWhales: 'திமிங்கலக் கையாளுதலைத் தடுத்தல்',
    preventingWhalesDesc: 'பெரிய முதலீட்டாளர்களுக்கு விகிதாசாரமாக வெகுமதி அளிக்கும் அதே வேளையில் எந்தவொரு நிறுவனமும் நெறிமுறையை கட்டுப்படுத்த முடியாது என்பதை எங்கள் புதிய வாக்களிப்பு தர்க்கம் உறுதி செய்கிறது.',
    encouragingEngagementDesc: 'வாக்களிப்பதற்கான எரியும் தேவை அர்த்தமுள்ள பங்கேற்பை ஊக்குவிக்கிறது மற்றும் அற்பமான அல்லது தீங்கிழைக்கும் வாக்களிப்பை ஊக்கப்படுத்துகிறது.',
    solvingTitle: 'ஆளுகை சிக்கல்களைத் தீர்ப்பது',
    solvingDesc: 'தற்போது, டோக்கன் நிர்வாகத்தின் மோசமான நற்பெயருக்கு மிகவும் மோசமான இரண்டு காரணங்கள் திமிங்கல கையாளுதல் மற்றும் பரந்த ஹோல்டர் தளத்திலிருந்து ஈடுபாடு இல்லாதது. மேற்கண்ட வாக்களிக்கும் தர்க்கம் மற்றும் விளையாட்டு கோட்பாடு உலகளவில் அங்கீகரிக்கப்பட்ட இந்த பிரச்சினைகளுக்கு ஒரு புதிய தீர்வை வழங்குகிறது, மேலும் டோக்கன் ஆளுகை சந்தேக நபர்களை தவறாக நிரூபிக்கும் என்று நாங்கள் நம்புகிறோம்.',
    launchNote: 'DeHub இன் ஆளுகை நெறிமுறை மேடையில் வெளிவருகிறது — திட்டங்கள் மற்றும் வாக்களிப்பு இன்று ஆப்பில் கிடைக்கின்றன.',
    stayTuned: 'மேலும் அறிய காத்திருங்கள்...',
    disclaimer: 'பொறுப்புத்துறப்பு',
    disclaimerText: 'DeHub டோக்கன்கள் எந்தவொரு விளையாட்டு அல்லது ஆப் டிஜிட்டல் டோக்கன்கள் அல்லது நாணயங்கள் மற்றும் கண்டிப்பாக முதலீடு செய்யாத அதே வழியில் பயன்பாட்டு நோக்கங்களுக்காக கண்டிப்பாக உள்ளன. எங்கள் டோக்கன் சங்கிலியில் இருப்பதால், கூடுதல் பயன்பாடு மற்றும் சரிபார்க்கக்கூடிய வெளிப்படைத்தன்மையின் முன்னோடியில்லாத அளவுகளை நாங்கள் வழங்க முடியும். மேற்கண்ட தரவு வெளிப்படைத்தன்மை, கல்வி மற்றும் தகவல் நோக்கங்களுக்காக மட்டுமே தொகுக்கப்பட்டுள்ளது. நாங்கள் வெளியிடும் டோக்கன்கள் அல்லது NFTகளை வாங்குவதால் ஏற்படும் நிதி இழப்புகளுக்கு DeHub மற்றும் அனைத்து துணை நிறுவனங்களும் பொறுப்பேற்காது. சந்தைகள் மிகவும் கொந்தளிப்பானவை. திறன் தோல்விகள், தொழில்நுட்பப் பிழைகள், ஹேக்குகள் போன்ற எதிர்பாராத பிழைகள் காரணமாக உங்கள் பணம் அனைத்தையும் நீங்கள் இழக்க நேரிடலாம். ஆகையால், நீங்கள் இழக்கக்கூடியதை மட்டுமே நீங்கள் செலவழிக்க வேண்டும்.',
