    introDesc: 'எல்லா d \'appகளிலும் மேம்பட்ட அம்சங்களை வெவ்வேறு கிளப் அடுக்குகளை அணுகுவதற்கும், நெறிமுறை வருவாயில் உங்கள் பங்கைச் சுரங்கப்படுத்த மொபைலாக இருந்து உங்கள் கம்ப்யூட்டிங் பவர் அல்லது ஸ்டோரேஜ் ஸ்பேஸை வழங்குவதற்கும் பங்கு கொள்ளுங்கள்.',
    introDesc2: 'மேலும் ஒதுக்கீடுகள் இப்போது மாறும் என்பதால், நெறிமுறைக் கட்டணங்களைப் பொறுத்து, நெறிமுறைத் தேவைகள் எல்லா நேரங்களிலும் முன்னணியில் இருப்பதை உறுதிசெய்து, எந்தவொரு தருணத்திலும் நியமனங்கள் தேவைகளுக்கு உட்பட்டதாக இருக்கும். ஸ்டேக்கிங் நெறிமுறையும் தற்போது பேஸில் விரைவில் வெளியிடப்பட்டு மேம்படுத்தப்பட்டு வருகிறது.',
    technicals: 'தொழில்நுட்பங்கள்',
    technicalsDesc1: 'கிளப்புகளில் சேர்வது உங்கள் dehub.io சுயவிவரம், கருத்துகள், பதிவேற்றங்கள் மற்றும் நேரடி அரட்டை தகவல்தொடர்புகளில் காட்டப்படும் கீழே உள்ள பேட்ஜ்களையும் திறக்கும்.',
    technicalsDesc2: 'DeHub டோக்கன்களின் அளவிற்கான சலுகைகளுக்கு அப்பால், பயனர் வெகுமதிகளை வரையறுக்கும் பங்கு காலத்தால் தீர்மானிக்கப்படும் மூன்று முன் வரையறுக்கப்பட்ட அடுக்குகளும் உள்ளன.',
