    tier2: 'அடுக்கு 2',
    tier2Rewards: '25% வெகுமதிகள்',
    tier2Desc: 'பங்கேற்பு செய்ய 3 முதல் 4 குவார்ட்டர்கள், மற்றும் பரிசுகளின் 25% பங்கை பகிர்ந்து கொள்ளுங்கள்.',
