    militaryGradeDesc: 'DeHub இல், உங்கள் உரையாடல்கள் முற்றிலும் தனிப்பட்டதாக இருப்பதை உறுதிசெய்ய இராணுவ-தர முனை-முதல்-முனை குறியாக்கத்தை (E2EE) செயல்படுத்தியுள்ளோம். நீங்கள் ஒரு செய்தியை அனுப்பும்போது, நீங்களும் உங்கள் பெறுநரும் மட்டுமே அதைப் படிக்க முடியும் - DeHub இன் சேவையகங்களுக்குக் கூட உங்கள் மறைகுறியாக்கப்பட்ட செய்திகளுக்கான அணுகல் இல்லை.',
