    xchacha2: 'இரகசியத்தன்மை (செய்திகளைப் படிக்க முடியாது) மற்றும் நம்பகத்தன்மை (செய்திகளைச் சிதைக்க முடியாது) ஆகிய இரண்டையும் வழங்குகிறது',
    xchacha3: 'மொபைல் சாதனங்களில் கூட மின்னல் வேக செயல்திறன்',
