    contactNote: 'இந்த தனியுரிமைக் கொள்கை சமூக நிர்வாக செயல்முறைகள் மூலம் புதுப்பிக்கப்படலாம். பொருள் மாற்றங்கள் எங்கள் அதிகாரப்பூர்வ சேனல்கள் மூலம் தெரிவிக்கப்படும்.',
    importantNoticeText: 'DeHub ஒரு பரவலாக்கப்பட்ட நெறிமுறையாக செயல்படுகிறது. பயனர் தனியுரிமையைப் பாதுகாக்க நாங்கள் பாடுபடுகையில், பரவலாக்கப்பட்ட இயல்பு என்பது பொது பிளாக்செயின்களில் தொடர்புகள் தெரியும் என்பதாகும். பயனர்கள் தங்கள் பிளாக்செயின் தொடர்புகளின் தனியுரிமை தாக்கங்களைப் புரிந்துகொள்வதற்கு பொறுப்பாவார்கள்.',
