    reportingItem3: 'உங்கள் பட்டியல்களிலிருந்து கணக்கை நீக்காமல் அதை மௌனமாக்கலாம்.',
    reportingItem4: 'அவசர அல்லது சட்ட விஷயங்களுக்கு, dev@dehub.io க்கு மின்னஞ்சல் அனுப்பவும்',
    whatHappensNext: 'அடுத்து என்ன நடக்கும்',
    whatHappensNextText: 'நியமிக்கப்பட்ட மதிப்பீட்டாளர்கள் — சமூகத்தால் தேர்ந்தெடுக்கப்பட்ட நிர்வாகிகள் மற்றும் உயர்மட்ட பேட்ஜ் வைத்திருப்பவர்கள் — ஆளுகை வாக்கெடுப்புக்காகக் காத்திருக்காமல் செயல்பட நியமிக்கப்பட்ட அதிகாரத்தை வைத்திருப்பவர்கள் மூலம் அறிக்கைகள் மதிப்பாய்வு செய்யப்படுகின்றன.',
    whatHappensNextItem1: 'இந்த வழிகாட்டுதல்களை மீறும் உள்ளடக்கம் அகற்றப்படும்',
    whatHappensNextItem2: 'தவறான நடத்தைக்கு பொறுப்பான கணக்குகள் இடைநிறுத்தப்படுகின்றன அல்லது கட்டுப்படுத்தப்படுகின்றன',
    whatHappensNextItem3: 'மீண்டும் மீண்டும் அல்லது கடுமையான மீறல்கள் கணக்கை நிரந்தரமாக அகற்ற வழிவகுக்கும்',
    whatHappensNextItem4: 'சட்டவிரோதப் பொருட்கள் சட்டத்தால் தேவைப்படும் இடங்களில் பொருத்தமான அதிகாரிகளுக்கு அதிகரிக்கப்படுகின்றன',
    appeals: 'மேல்முறையீடுகள்',
    appealsText: 'மிதமான முடிவு தவறானது என்று நீங்கள் நம்பினால், அதை சமூக ஆளுகை மூலம் முறையிடலாம். கொள்கை மதிப்பீட்டாளர்கள் செயல்படுத்துவதை ஆளுகை அமைக்கிறது மற்றும் தனிப்பட்ட முடிவுகளை மதிப்பாய்வு செய்யலாம் அல்லது தலைகீழாக மாற்றலாம். இருப்பினும், அமலாக்கம் உடனடியாக உள்ளது — மேல்முறையீடு பரிசீலிக்கப்படும் போது உள்ளடக்கம் கீழே இருக்கும்.',
